export function writeFxOutline(w: Writer, v: FxOutline, t: Tables): void {
  void t;
  w.bitmap([v.dash !== undefined]);
  w.f64(v.widthPt);
  writeResolvedFill(w, v.fill, t);
  if (v.dash !== undefined) {
    w.u32(t.sym.intern(v.dash));
  }
  writeLineCap(w, v.cap, t);
  writeLineJoin(w, v.join, t);
}

export function readFxOutline(r: Reader, t: Tables): FxOutline {
  void t;
  const bm = r.bitmap(1);
  const f_width_pt = r.f64();
  const f_fill = readResolvedFill(r, t);
  let f_dash: string | undefined;
  if (bitAt(bm, 0)) f_dash = t.sym.list[r.ref(0, "sym")]!;
  const f_cap = readLineCap(r, t);
  const f_join = readLineJoin(r, t);
  const o: FxOutline = { widthPt: f_width_pt, fill: f_fill, cap: f_cap, join: f_join };
  if (f_dash !== undefined) o.dash = f_dash;
  return o;
}

