  const o: FxShadow = { blurPt: f_blur_pt, distPt: f_dist_pt, dirDeg: f_dir_deg, sx: f_sx, sy: f_sy, kxDeg: f_kx_deg, kyDeg: f_ky_deg, algn: f_algn, hex: f_hex, alpha: f_alpha };
