/**
 */
export interface TextFx {
  fill?: ResolvedFill;
  outline?: FxOutline;
  shadow?: FxShadow;
  glow?: FxGlow;
  reflection?: FxReflection;
}

export function writeTextFx(w: Writer, v: TextFx, t: Tables): void {
  void t;
  w.bitmap([v.fill !== undefined, v.outline !== undefined, v.shadow !== undefined, v.glow !== undefined, v.reflection !== undefined]);
  if (v.fill !== undefined) {
    writeResolvedFill(w, v.fill, t);
  }
  if (v.outline !== undefined) {
    writeFxOutline(w, v.outline, t);
  }
  if (v.shadow !== undefined) {
    writeFxShadow(w, v.shadow, t);
  }
  if (v.glow !== undefined) {
    writeFxGlow(w, v.glow, t);
  }
  if (v.reflection !== undefined) {
    writeFxReflection(w, v.reflection, t);
  }
}

export function readTextFx(r: Reader, t: Tables): TextFx {
  void t;
  const bm = r.bitmap(5);
  let f_fill: ResolvedFill | undefined;
  if (bitAt(bm, 0)) f_fill = readResolvedFill(r, t);
  let f_outline: FxOutline | undefined;
  if (bitAt(bm, 1)) f_outline = readFxOutline(r, t);
  let f_shadow: FxShadow | undefined;
  if (bitAt(bm, 2)) f_shadow = readFxShadow(r, t);
  let f_glow: FxGlow | undefined;
  if (bitAt(bm, 3)) f_glow = readFxGlow(r, t);
  let f_reflection: FxReflection | undefined;
  if (bitAt(bm, 4)) f_reflection = readFxReflection(r, t);
  const o: TextFx = {  };
  if (f_fill !== undefined) o.fill = f_fill;
  if (f_outline !== undefined) o.outline = f_outline;
  if (f_shadow !== undefined) o.shadow = f_shadow;
  if (f_glow !== undefined) o.glow = f_glow;
  if (f_reflection !== undefined) o.reflection = f_reflection;
  return o;
}

