/**
 * PageFillPaint (page-fill.ts:44).
 */
export interface PageFill {
  type: PageFillKind;
  c1: string;
  c2: string;
  stops?: GradStop[];
  angle: number;
  focus: number;
  focusPosition?: FocusPosition;
  gradientCenter?: boolean;
  image?: number;
  imagePx?: ImagePx;
  pattern?: number[];
}

export function writePageFill(w: Writer, v: PageFill, t: Tables): void {
  void t;
  w.bitmap([v.stops !== undefined, v.focusPosition !== undefined, !!v.gradientCenter, v.image !== undefined, v.imagePx !== undefined, v.pattern !== undefined]);
  writePageFillKind(w, v.type, t);
  w.u32(t.sym.intern(v.c1));
  w.u32(t.sym.intern(v.c2));
  if (v.stops !== undefined) {
    w.len(v.stops.length);
    for (const e0 of v.stops) {
      writeGradStop(w, e0, t);
    }
  }
  w.f64(v.angle);
  w.f64(v.focus);
  if (v.focusPosition !== undefined) {
    writeFocusPosition(w, v.focusPosition, t);
  }
  if (v.image !== undefined) {
    w.u32(v.image);
  }
  if (v.imagePx !== undefined) {
    writeImagePx(w, v.imagePx, t);
  }
  if (v.pattern !== undefined) {
    w.len(v.pattern.length);
    for (const e0 of v.pattern) {
      w.f64(e0);
    }
  }
}

export function readPageFill(r: Reader, t: Tables): PageFill {
  void t;
  const bm = r.bitmap(6);
  const f_kind = readPageFillKind(r, t);
  const f_c1 = t.sym.list[r.ref(0, "sym")]!;
  const f_c2 = t.sym.list[r.ref(0, "sym")]!;
  let f_stops: GradStop[] | undefined;
  if (bitAt(bm, 0)) f_stops = r.list(72, () => readGradStop(r, t));
  const f_angle = r.f64();
  const f_focus = r.f64();
  let f_focus_position: FocusPosition | undefined;
  if (bitAt(bm, 1)) f_focus_position = readFocusPosition(r, t);
  const f_gradient_center = bitAt(bm, 2);
  let f_image: number | undefined;
  if (bitAt(bm, 3)) f_image = r.ref(2, "images");
  let f_image_px: ImagePx | undefined;
  if (bitAt(bm, 4)) f_image_px = readImagePx(r, t);
  let f_pattern: number[] | undefined;
  if (bitAt(bm, 5)) f_pattern = r.list(64, () => r.f64());
  const o: PageFill = { type: f_kind, c1: f_c1, c2: f_c2, angle: f_angle, focus: f_focus, gradientCenter: f_gradient_center };
  if (f_stops !== undefined) o.stops = f_stops;
  if (f_focus_position !== undefined) o.focusPosition = f_focus_position;
  if (f_image !== undefined) o.image = f_image;
  if (f_image_px !== undefined) o.imagePx = f_image_px;
  if (f_pattern !== undefined) o.pattern = f_pattern;
  return o;
}

/** docx-core CustCmd. */
export type CustCmd =
  | ({ op: "M" } & Pt)
  | ({ op: "L" } & Pt)
  | ({ op: "C" } & CustPts)
  | ({ op: "Q" } & CustPts)
  | ({ op: "A" } & CustArc)
  | { op: "Z" };


export function writeCustCmd(w: Writer, v: CustCmd, t: Tables): void {
  void t;
  switch (v.op) {
    case "M":
      w.u32(0);
      writePt(w, v, t);
      break;

    case "L":
      w.u32(1);
      writePt(w, v, t);
      break;

    case "C":
      w.u32(2);
      writeCustPts(w, v, t);
      break;

    case "Q":
      w.u32(3);
      writeCustPts(w, v, t);
      break;

    case "A":
      w.u32(4);
      writeCustArc(w, v, t);
      break;

    case "Z":
      w.u32(5);
      break;

    default:
      throw new EncodeError(`"${String((v as { op: string }).op)}" is not a variant of CustCmd`);

  }
}

export function readCustCmd(r: Reader, t: Tables): CustCmd {
  void t;
  const tag = r.u32();
  let out: CustCmd;
  switch (tag) {
    case 0:
      out = Object.assign(readPt(r, t), { op: "M" as const });
      break;

    case 1:
      out = Object.assign(readPt(r, t), { op: "L" as const });
      break;

    case 2:
      out = Object.assign(readCustPts(r, t), { op: "C" as const });
      break;

    case 3:
      out = Object.assign(readCustPts(r, t), { op: "Q" as const });
      break;

    case 4:
      out = Object.assign(readCustArc(r, t), { op: "A" as const });
      break;

    case 5:
      out = { op: "Z" };
      break;

    default:
      throw new DecodeError("BadTag", `${tag} is not a variant of CustCmd`);

  }
  return out;
}

