/** What a decoder has received so far in one generation, and what an encoder keeps: the entries of every table (ids are positions). */
export interface Tables {
  generation: number | undefined;
  sym: SymTable;
  faces: Face[];
  images: Image[];
  textFx: TextFx[];
  pageFills: PageFill[];
  cust: CustGeom[];
}

export function newTables(): Tables {
  return { generation: undefined, sym: new SymTable(), faces: [], images: [], textFx: [], pageFills: [], cust: [] };
}

/** The number of entries of every table, in declaration order. */
export function tableLens(t: Tables): number[] {
  return [t.sym.length, t.faces.length, t.images.length, t.textFx.length, t.pageFills.length, t.cust.length];
}

/** The encoder's state: the tables (symbols are interned into them), how much of each was already sent, and the generation. */
export interface EncodeState {
  generation: number;
  tables: Tables;
  /** Per table, the entries before this index were sent by earlier messages. */
  sent: number[];
}

export function newEncodeState(generation: number, tables: Tables = newTables()): EncodeState {
  return { generation, tables, sent: new Array<number>(6).fill(0) };
}

/** Reads a `Page` message. `tables` is the state of this stream of messages: the new entries are appended, a new generation replaces them, and an error leaves them as they were. */
export function decodePage(buf: Uint8Array, tables: Tables, limits: Limits = DEFAULT_LIMITS): Page {
  const r = new Reader(buf, limits);
  const head = r.header(MAGIC, SCHEMA_HASH);
  if (head.message !== MSG_PAGE) throw new DecodeError("WrongMessage", `message id ${head.message}, expected ${MSG_PAGE}`);
  const reset = tables.generation !== head.generation;
  const saved = reset ? { generation: tables.generation, sym: tables.sym, faces: tables.faces, images: tables.images, textFx: tables.textFx, pageFills: tables.pageFills, cust: tables.cust } : undefined;
  if (reset) Object.assign(tables, newTables());
  const lens = tableLens(tables);
  try {
    const n_sym = r.tableHeader(0, "sym", tables.sym.length, 8);
    const n_faces = r.tableHeader(1, "faces", tables.faces.length, 32);
    const n_images = r.tableHeader(2, "images", tables.images.length, 152);
    const n_textFx = r.tableHeader(3, "text_fx", tables.textFx.length, 8);
    const n_pageFills = r.tableHeader(4, "page_fills", tables.pageFills.length, 160);
    const n_cust = r.tableHeader(5, "cust", tables.cust.length, 8);
    for (let i = 0; i < n_sym; i++) tables.sym.push(r.utf16());
    for (let i = 0; i < n_faces; i++) tables.faces.push(readFace(r, tables));
    for (let i = 0; i < n_images; i++) tables.images.push(readImage(r, tables));
    for (let i = 0; i < n_textFx; i++) tables.textFx.push(readTextFx(r, tables));
    for (let i = 0; i < n_pageFills; i++) tables.pageFills.push(readPageFill(r, tables));
    for (let i = 0; i < n_cust; i++) tables.cust.push(readCustGeom(r, tables));
    const msg = readPage(r, tables);
    r.end();
    tables.generation = head.generation;
    return msg;
  } catch (e) {
    if (saved) {
      Object.assign(tables, saved);
    } else {
      tables.sym.truncate(lens[0]!);
      tables.faces.length = lens[1]!;
      tables.images.length = lens[2]!;
      tables.textFx.length = lens[3]!;
      tables.pageFills.length = lens[4]!;
      tables.cust.length = lens[5]!;
    }
    throw e;
  }
}

/** Writes a `Page` message: the header, the new entries of every table (those past `state.sent`), the body. Symbols are interned into `state.tables`. */
export function encodePage(msg: Page, state: EncodeState): Uint8Array {
  const t = state.tables;
  const entries = new Writer();
  for (let i = state.sent[1]!; i < t.faces.length; i++) writeFace(entries, t.faces[i]!, t);
  for (let i = state.sent[2]!; i < t.images.length; i++) writeImage(entries, t.images[i]!, t);
  for (let i = state.sent[3]!; i < t.textFx.length; i++) writeTextFx(entries, t.textFx[i]!, t);
  for (let i = state.sent[4]!; i < t.pageFills.length; i++) writePageFill(entries, t.pageFills[i]!, t);
  for (let i = state.sent[5]!; i < t.cust.length; i++) writeCustGeom(entries, t.cust[i]!, t);
  const body = new Writer();
  writePage(body, msg, t);
  const w = new Writer();
  w.header(MAGIC, SCHEMA_HASH, MSG_PAGE, state.generation);
  w.u32(state.sent[0]!);
  w.len(t.sym.length - state.sent[0]!);
  w.u32(state.sent[1]!);
  w.len(t.faces.length - state.sent[1]!);
  w.u32(state.sent[2]!);
  w.len(t.images.length - state.sent[2]!);
  w.u32(state.sent[3]!);
  w.len(t.textFx.length - state.sent[3]!);
  w.u32(state.sent[4]!);
  w.len(t.pageFills.length - state.sent[4]!);
  w.u32(state.sent[5]!);
  w.len(t.cust.length - state.sent[5]!);
  for (let i = state.sent[0]!; i < t.sym.length; i++) w.utf16(t.sym.list[i]!);
  w.raw(entries);
  w.raw(body);
  state.sent = tableLens(t);
  return w.finish();
}
